export const IS_CONTRACT_CONFIGURED = Array.isArray(CONTRACT_ABI) && CONTRACT_ABI.length > 0;

// Bytecode compiled của HuiDauROSCA — BẮT BUỘC để deploy 1 contract mới cho mỗi
// dây hụi (xem createGroupOnChain bên dưới). Lấy trong Remix: tab "Solidity
// Compiler" → nút "Bytecode" → copy giá trị field "object" và dán vào đây.
export const CONTRACT_BYTECODE =
  "";

export const IS_BYTECODE_CONFIGURED = Boolean(CONTRACT_BYTECODE);

// Contract instance theo địa chỉ riêng của từng dây hụi (mỗi group = 1 contract).
export function getGroupContract(runner: ContractRunner, groupContractAddress: string) {
  return new Contract(groupContractAddress, CONTRACT_ABI, runner);
}

// Lấy signer từ ví MetaMask đang kết nối — dùng ngay trước khi gửi giao dịch,
// không cache lại vì signer có thể đổi theo tài khoản/mạng hiện tại của ví.
export async function getBrowserSigner(): Promise<Signer> {
  // MOCK: trả signer giả (không dùng thật vì các hàm hành động đã short-circuit).
  if (MOCK_MODE) return {} as unknown as Signer;
  if (!window.ethereum) {
    throw new Error("Chưa cài đặt MetaMask.");
  }
  const provider = new BrowserProvider(window.ethereum);
  return provider.getSigner();
}

export type CreateGroupParams = {
  name: string;
  shareAmountWei: bigint;
  totalMembers: number;
  collateralWei: bigint;
  roundDurationSec: number;
  bidDurationSec: number;
};

export type CreateGroupResult = {
  contractAddress: string;
  txHash: string;
};

// Deploy 1 contract HuiDauROSCA MỚI cho dây hụi này — người gọi (ví MetaMask hiện
// tại) trở thành `organizer`. Đây là hành động on-chain thật, tốn gas thật (ETH
// Sepolia testnet) của người tạo dây.
export async function createGroupOnChain(
  signer: Signer,
  params: CreateGroupParams
): Promise<CreateGroupResult> {
  if (MOCK_MODE) {
    await mockDelay();
    return { contractAddress: mockContractAddress(), txHash: mockTxHash() };
  }
  if (!IS_CONTRACT_CONFIGURED) {
    throw new Error("Chưa cấu hình ABI contract thật.");
  }
  if (!IS_BYTECODE_CONFIGURED) {
    throw new Error(
      "Chưa cấu hình CONTRACT_BYTECODE trong lib/contract.ts — cần bytecode (không chỉ ABI) để deploy contract mới cho mỗi dây hụi. Lấy từ Remix: Solidity Compiler → Bytecode."
    );
  }
  const factory = new ContractFactory(CONTRACT_ABI, CONTRACT_BYTECODE, signer);
  const contract = await factory.deploy(
    params.shareAmountWei,
    params.totalMembers,
    params.collateralWei,
    params.roundDurationSec,
    params.bidDurationSec
  );
  await contract.waitForDeployment();
  const contractAddress = await contract.getAddress();
  const deployTx = contract.deploymentTransaction();
  return {
    contractAddress,
    txHash: deployTx?.hash ?? "",
  };
}

// Tham gia dây hụi: gửi đúng collateralAmount làm ký quỹ.
export async function joinGroupOnChain(
  signer: Signer,
  groupContractAddress: string,
  collateralWei: bigint
): Promise<{ txHash: string }> {
  if (MOCK_MODE) {
    await mockDelay();
    return { txHash: mockTxHash() };
  }
  if (!IS_CONTRACT_CONFIGURED) {
    throw new Error("Chưa cấu hình ABI contract thật.");
  }
  const contract = getGroupContract(signer, groupContractAddress);
  const tx = await contract.join({ value: collateralWei });
  await tx.wait();
  return { txHash: tx.hash };
}

