export type RoundInfoOnChain = {
  winnerAddress: string;
  winningBidWei: bigint;
  requiredFromSurvivorWei: bigint;
  requiredFromDeadWei: bigint;
  totalCollectedWei: bigint;
  bidClosed: boolean;
  settled: boolean;
};

// Đọc thông tin 1 vòng đấu trực tiếp từ contract (view, không tốn gas).
export async function getRoundInfoOnChain(
  groupContractAddress: string,
  roundNumber: number
): Promise<RoundInfoOnChain> {
  if (!window.ethereum) {
    throw new Error("Chưa cài đặt MetaMask.");
  }
  const provider = new BrowserProvider(window.ethereum);
  const contract = getGroupContract(provider, groupContractAddress);
  const info = await contract.getRoundInfo(roundNumber);
  return {
    winnerAddress: info.winner,
    winningBidWei: info.winningBid,
    requiredFromSurvivorWei: info.requiredFromSurvivor,
    requiredFromDeadWei: info.requiredFromDead,
    totalCollectedWei: info.totalCollected,
    bidClosed: info.bidClosed,
    settled: info.settled,
  };
}

export type CloseRoundResult = {
  txHash: string;
  winnerAddress: string;
  winningBidWei: bigint;
  requiredFromSurvivorWei: bigint;
  requiredFromDeadWei: bigint;
};

// Chốt vòng đấu hiện tại. Đọc currentRound() TRƯỚC khi gọi closeRound() vì contract
// có thể tự mở vòng kế tiếp (currentRound tăng lên) ngay sau khi đóng vòng này.
export async function closeRoundOnChain(
  signer: Signer,
  groupContractAddress: string
): Promise<CloseRoundResult> {
  if (MOCK_MODE) {
    await mockDelay();
    return {
      txHash: mockTxHash(),
      winnerAddress: MOCK_ADDRESS.toLowerCase(),
      winningBidWei: BigInt("50000000000000000"), // 0.05 ETH
      requiredFromSurvivorWei: BigInt("450000000000000000"),
      requiredFromDeadWei: BigInt("500000000000000000"),
    };
  }
  if (!IS_CONTRACT_CONFIGURED) {
    throw new Error("Chưa cấu hình ABI contract thật.");
  }
  const contract = getGroupContract(signer, groupContractAddress);
  const roundNumberBeingClosed: bigint = await contract.currentRound();
  const tx = await contract.closeRound();
  await tx.wait();
  const info = await getRoundInfoOnChain(groupContractAddress, Number(roundNumberBeingClosed));
  return {
    txHash: tx.hash,
    winnerAddress: info.winnerAddress,
    winningBidWei: info.winningBidWei,
    requiredFromSurvivorWei: info.requiredFromSurvivorWei,
    requiredFromDeadWei: info.requiredFromDeadWei,
  };
}

