// Đọc trần lãi ĐỘNG của kỳ hiện tại từ contract (view, không tốn gas) — gọi hàm
// currentMaxBidCap() được tính lại mỗi kỳ theo đúng công thức Điều 21 Nghị định
// 19/2019: trần = 20%/năm × (n-k+1)×P × [(n-k)×t/365], với k = kỳ đang hốt, n =
// số thành viên, P = phần hụi, t = thời lượng kỳ. Trần cao khi hốt sớm, giảm dần
// và bằng 0 ở kỳ cuối cùng (k = n). Trả về null nếu không có provider (chưa cài
// MetaMask) để UI fallback sang ước tính client-side.
export async function getCurrentMaxBidCapOnChain(
  groupContractAddress: string
): Promise<bigint | null> {
  if (!IS_CONTRACT_CONFIGURED || !window.ethereum) return null;
  const provider = new BrowserProvider(window.ethereum);
  const contract = getGroupContract(provider, groupContractAddress);
  return contract.currentMaxBidCap();
}

// Alias giữ tương thích ngược cho code cũ còn gọi tên hàm trước đây.
export const getMaxBidCapOnChain = getCurrentMaxBidCapOnChain;

// Đọc địa chỉ organizer thật từ contract — dùng để quyết định ai được thấy nút
